import{_ as t,c as a,o,a3 as s}from"./chunks/framework.Dokpd4od.js";const u=JSON.parse('{"title":"Point of Sale reporting","description":"","frontmatter":{},"headers":[],"relativePath":"master/sales/point-of-sale/reporting/index.md","filePath":"master/sales/point-of-sale/reporting/index.md","lastUpdated":1793074831000}'),r={name:"master/sales/point-of-sale/reporting/index.md"};function d(n,e,i,h,l,c){return o(),a("div",null,e[0]||(e[0]=[s('<h1 id="point-of-sale-reporting" tabindex="-1">Point of Sale reporting <a class="header-anchor" href="#point-of-sale-reporting" aria-label="Permalink to &quot;Point of Sale reporting&quot;">​</a></h1><p>Point of Sale reporting shows you what your registers sold, how customers paid and whether the cash drawer matched at closing. You have one dashboard for a quick look and three reports for detail. Each one answers a different question.</p><blockquote><p><strong>In simple words:</strong> Use the dashboard for a fast health check, then open a report when you need exact numbers.</p></blockquote><h2 id="which-page-answers-which-question" tabindex="-1">Which page answers which question <a class="header-anchor" href="#which-page-answers-which-question" aria-label="Permalink to &quot;Which page answers which question&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Question</th><th>Page</th><th>Path</th></tr></thead><tbody><tr><td>Which registers are open, and what was the last closing balance?</td><td><a href="./dashboard.html">Dashboard</a></td><td><code>Point of Sale → Dashboard</code></td></tr><tr><td>How many sessions are open, and what is my revenue and best seller?</td><td><a href="./dashboard.html">Dashboard</a></td><td><code>Point of Sale</code> (top bar)</td></tr><tr><td>How many orders did I take each day, week or month?</td><td><a href="./orders-report.html">Orders report</a></td><td><code>Point of Sale → Reporting → Orders</code></td></tr><tr><td>What did I sell, how was it paid and how much tax did I collect?</td><td><a href="./sales-details.html">Sales details</a></td><td><code>Point of Sale → Reporting → Sales Details</code></td></tr><tr><td>Did the cash drawer balance for one session?</td><td><a href="./session-report.html">Session report</a></td><td><code>Point of Sale → Reporting → Session Report</code></td></tr></tbody></table><h2 id="what-counts-as-a-sale" tabindex="-1">What counts as a sale <a class="header-anchor" href="#what-counts-as-a-sale" aria-label="Permalink to &quot;What counts as a sale&quot;">​</a></h2><p>All three reports count only settled orders. A settled order has the status <strong>Paid</strong>, <strong>Posted</strong> or <strong>Invoiced</strong>. Orders in <strong>New</strong> or <strong>Cancelled</strong> status never appear in the totals.</p><p>A refund is also an order, but its amount is negative. It reduces your totals. See <a href="./../selling/refunds.html">Refunds</a> for how a refund is created.</p><h2 id="sample-data-used-in-this-section" tabindex="-1">Sample data used in this section <a class="header-anchor" href="#sample-data-used-in-this-section" aria-label="Permalink to &quot;Sample data used in this section&quot;">​</a></h2><p>The pages use the TechNest Electronics register and its closed session TNE/SESSION/00002.</p><table tabindex="0"><thead><tr><th>Order</th><th>Customer</th><th>What was sold</th><th>Total</th></tr></thead><tbody><tr><td>TNE/00001</td><td>Sofia Rossi</td><td>2 Glide Wireless Mouse, 1 BudsAir Wireless Earbuds</td><td>6,597.00</td></tr><tr><td>TNE/00002</td><td>Tom Baker</td><td>1 Nova X5 Smartphone 128GB</td><td>24,999.00</td></tr><tr><td>TNE/00002 refund</td><td>Tom Baker</td><td>The same smartphone, returned</td><td>-24,999.00</td></tr></tbody></table><p>Together the three orders add up to 6,597.00.</p><h2 id="good-habits" tabindex="-1">Good habits <a class="header-anchor" href="#good-habits" aria-label="Permalink to &quot;Good habits&quot;">​</a></h2><ul><li>Close each session at the end of the shift. The session report is complete only after closing.</li><li>Check the dashboard each morning for sessions that stay open for days.</li><li>Set the same date range on the report and on your accounting records when you compare them.</li></ul><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./../">Point of Sale overview</a></li><li><a href="./../sessions/close-session.html">Close a session</a></li><li><a href="./../orders-payments/orders.html">Orders</a></li></ul>',16)]))}const f=t(r,[["render",d]]);export{u as __pageData,f as default};
